import sys
from collections import deque

q1 = deque()
q2 = deque()

def push(x):
    global q1, q2
    q2.append(x)
    while q1:
        q2.append(q1.popleft())
    q1, q2 = q2, q1

def pop():
    global q1
    if q1:
        return q1.popleft()
    return -1

def peek():
    global q1
    if q1:
        return q1[0]
    return -1

def main():
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        tokens = line.split()
        if tokens[0] == 'push':
            x = int(tokens[1])
            push(x)
        elif tokens[0] == 'pop':
            result = pop()
            print(result)
        elif tokens[0] == 'peek':
            result = peek()
            print(result)

if __name__ == "__main__":
    main()
